@@ -315,18 +315,22 @@ typedef struct {
     PyObject *default_value;
 } anextawaitableobject;

+#define anextawaitableobject_CAST(op)   ((anextawaitableobject *)(op))
+
 static void
-anextawaitable_dealloc(anextawaitableobject *obj)
